import React from 'react'
import { LandImageContainer, LandImageContainerVW, LandImageContainerVH } from './styles';

interface PropertyImages{
    image:string
}

const LandImages = ({image}: PropertyImages) =>{

    const images: PropertyImages[] = [
        {

            image: "https://www.themoviedb.org/t/p/w533_and_h300_bestv2/jBJWaqoSCiARWtfV0GlqHrcdidd.jpg"
           
        }
        
    ]



    return (
        <LandImageContainer>
            <LandImageContainerVW>
                {images.map(image => <LandImages {...image} />)}

            </LandImageContainerVW>
            <LandImageContainerVH>

            </LandImageContainerVH>
        </LandImageContainer>
    )
}

export default LandImages
